def page(filename, title, description, content):
    business = {'@context':'https://schema.org','@type':'HomeAndConstructionBusiness','name':'Menglong Doors & Windows','description':'Aluminium doors and windows in Phnom Penh, Cambodia.','telephone':'+85599881199','email':EMAIL,'sameAs':[FB],'address':{'@type':'PostalAddress','streetAddress':'No. 261K, San Han Street, Toul Sangke 1, Russey Keo','addressLocality':'Phnom Penh','addressCountry':'KH'}}
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Menglong Doors &amp; Windows</title><meta name="description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#192c32"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | Menglong Doors &amp; Windows"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:image" content="{IMG}sliding-door.jpg"><link rel="icon" type="image/jpeg" href="{IMG}logo.jpg"><link rel="alternate" hreflang="en" href="{filename}" data-language="en"><link rel="alternate" hreflang="km" href="km/{filename}" data-language="km"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Battambang:wght@400;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/menglong.css?v={CSS_VERSION}"><script src="assets/js/menglong.js?v={JS_VERSION}" defer></script><script type="application/ld+json">{json.dumps(business,ensure_ascii=False)}</script></head><body>{header(filename)}<main id="main">{content}</main>{footer()}</body></html>'''
    html = html.replace('<body>', f'<body class="page-{filename.removesuffix(".html")}">')
    (ROOT / 'en').mkdir(exist_ok=True)
    english = html.replace('="assets/', '="../assets/').replace('href="km/', 'href="../km/')
    (ROOT / 'en' / filename).write_text(english.replace('><', '>\n<'), encoding='utf-8')
    (ROOT / 'km').mkdir(exist_ok=True)
    khmer = localize(html, filename).replace('><', '>\n<')
    (ROOT / 'km' / filename).write_text(khmer, encoding='utf-8')
    # Root URLs render English immediately, including when opened as local files.
    default = html.replace('><', '>\n<')
    (ROOT / filename).write_text(default, encoding='utf-8')

